import org.apache.commons.csv.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;

public class Probe {
    public static void main(String[] args) throws Exception {
        Class<?> cls = Class.forName("org.apache.commons.csv.ExtendedBufferedReader");
        Constructor<?> ctor1 = cls.getDeclaredConstructor(Reader.class);
        ctor1.setAccessible(true);
        Constructor<?> ctor2 = cls.getDeclaredConstructor(Reader.class, java.nio.charset.Charset.class, boolean.class);
        ctor2.setAccessible(true);

        Method read0 = cls.getDeclaredMethod("read"); read0.setAccessible(true);
        Method readBuf = cls.getDeclaredMethod("read", char[].class, int.class, int.class); readBuf.setAccessible(true);
        Method getPosition = cls.getDeclaredMethod("getPosition"); getPosition.setAccessible(true);
        Method getLineNumber = cls.getDeclaredMethod("getLineNumber"); getLineNumber.setAccessible(true);
        Method getLastChar = cls.getDeclaredMethod("getLastChar"); getLastChar.setAccessible(true);
        Method getBytesRead = cls.getDeclaredMethod("getBytesRead"); getBytesRead.setAccessible(true);
        Method mark = cls.getDeclaredMethod("mark", int.class); mark.setAccessible(true);
        Method reset = cls.getDeclaredMethod("reset"); reset.setAccessible(true);
        Method peek = cls.getMethod("peek"); // probably public in parent? let's check

        // Test 1: position behavior reading past EOF repeatedly with plain reader
        Object r1 = ctor1.newInstance(new StringReader("ab"));
        System.out.println("read: " + read0.invoke(r1)); // a
        System.out.println("read: " + read0.invoke(r1)); // b
        System.out.println("read: " + read0.invoke(r1)); // EOF
        System.out.println("position after 1st EOF: " + getPosition.invoke(r1));
        System.out.println("read: " + read0.invoke(r1)); // EOF again
        System.out.println("position after 2nd EOF: " + getPosition.invoke(r1));
        System.out.println("read: " + read0.invoke(r1)); // EOF again
        System.out.println("position after 3rd EOF: " + getPosition.invoke(r1));

        // Test 2: bulk read position at EOF
        Object r2 = ctor1.newInstance(new StringReader("ab"));
        char[] buf = new char[5];
        System.out.println("bulk read len: " + readBuf.invoke(r2, buf, 0, 5));
        System.out.println("position: " + getPosition.invoke(r2));
        System.out.println("bulk read len (at EOF): " + readBuf.invoke(r2, buf, 0, 5));
        System.out.println("position after EOF bulk read: " + getPosition.invoke(r2));

        // Test 3: encoder + EOF via single read()
        Object r3 = ctor2.newInstance(new StringReader("a"), StandardCharsets.UTF_8, true);
        System.out.println("read: " + read0.invoke(r3));
        try {
            Object res = read0.invoke(r3); // should hit EOF with encoder enabled
            System.out.println("read at EOF with encoder: " + res);
            System.out.println("bytesRead: " + getBytesRead.invoke(r3));
        } catch (InvocationTargetException e) {
            System.out.println("Exception on EOF read with encoder: " + e.getCause());
        }

        // Test 4: mark/reset
        Object r4 = ctor1.newInstance(new StringReader("abc\ndef"));
        read0.invoke(r4); // a
        mark.invoke(r4, 10);
        read0.invoke(r4); // b
        read0.invoke(r4); // c
        read0.invoke(r4); // \n
        System.out.println("before reset: pos=" + getPosition.invoke(r4) + " line=" + getLineNumber.invoke(r4) + " lastChar=" + getLastChar.invoke(r4));
        reset.invoke(r4);
        System.out.println("after reset: pos=" + getPosition.invoke(r4) + " line=" + getLineNumber.invoke(r4) + " lastChar=" + getLastChar.invoke(r4));
        System.out.println("read after reset: " + (char)(int)(Integer)read0.invoke(r4));
    }
}
EOF
